-- =================================================================================================
-- (by hand) Row security: the same rule as every organization table
-- =================================================================================================
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['students', 'student_status_changes', 'guardians', 'student_guardians', 'enrolments'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY organization_isolation ON %I
         USING (current_setting(''app.bypass_rls'', true) = ''on''
                OR "organization_id"::text = current_setting(''app.organization_id'', true))
         WITH CHECK (current_setting(''app.bypass_rls'', true) = ''on''
                OR "organization_id"::text = current_setting(''app.organization_id'', true))', t);
  END LOOP;
END
$$;

-- (by hand) A roll number is unique within a section in a year (when given).
CREATE UNIQUE INDEX "enrolments_roll_no_key"
  ON "enrolments" ("class_id", "academic_year_id", "roll_no") WHERE "roll_no" IS NOT NULL;
